mapper.select:
SELECT * FROM transactions
WHERE from_wallet_id = #{walletId}
   OR to_wallet_id = #{walletId}
ORDER BY created_at DESC

SELECT t.id, t.from_wallet_id, t.to_wallet_id, t.amount, t.tx_type, t.status, t.created_at, fu.username AS from_username, tu.username AS to_username FROM transactions t LEFT JOIN wallets fw ON t.from_wallet_id = fw.id LEFT JOIN users fu ON fw.user_id = fu.id LEFT JOIN wallets tw ON t.to_wallet_id = tw.id LEFT JOIN users tu ON tw.user_id = tu.id
(fu.username ILIKE '%' || #{username} || '%' OR tu.username ILIKE '%' || #{username} || '%')
AND t.created_at >= #{fromDate}
AND t.created_at < #{toDate}::date + INTERVAL '1 day'
ORDER BY t.created_at DESC LIMIT #{limit} OFFSET #{offset}

SELECT * FROM transactions
WHERE from_wallet_id = #{walletId}
   OR to_wallet_id = #{walletId}
ORDER BY created_at DESC
LIMIT #{limit}
